      "id": 1,
      "claim": "Kinases are enzymes that catalyze the transfer of a phosphate group from ATP to specific amino‑acid residues on target proteins (phosphorylation).",
      "evidence": "Standard biochemical definition of protein kinases; they add phosphate groups, whereas phosphatases remove them.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The src oncogene encodes the protein pp60src, which possesses intrinsic tyrosine‑kinase activity.",
      "evidence": "Molecular studies of viral src (v‑src) and cellular src (c‑src) show they are non‑receptor tyrosine kinases that phosphorylate tyrosine residues on cellular proteins.",
      "weight": 0.45,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Only the option “Tyrosine kinase” (choice D) satisfies both conditions: it adds phosphate groups to proteins and is the activity encoded by src.",
      "evidence": "Option A (protein phosphatase) removes phosphates; B (adenylate cyclase) synthesizes cAMP; C (G‑protein‑linked receptor) is a receptor, not a kinase.",
      "weight": 0.25,
      "depends_on": [1, 2]
    }
  ],
  "answer": "D",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Protein phosphatases remove phosphate groups rather than add them."
    },
    {
      "answer": "B",
      "reason_rejected": "Adenylate cyclase generates cAMP from ATP and does not phosphorylate proteins."
    },
    {
      "answer": "C",
      "reason_rejected": "G‑protein‑linked receptors are membrane receptors, not enzymes that add phosphate groups."
    }
  ]
}
